import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';
import { PasswordField } from './PasswordField';

describe('PasswordField', () => {
  it('renderiza com o estado inicial', () => {
    render(<PasswordField value="" onChange={() => {}} />);

    expect(screen.getByLabelText('Senha')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Mostrar senha' })).toBeInTheDocument();
    expect(screen.queryByText(/Força:/)).not.toBeInTheDocument();
  });

  it('altera a visibilidade da senha', async () => {
    const user = userEvent.setup();
    render(<PasswordField value="senha123" onChange={() => {}} />);

    const toggleButton = screen.getByRole('button', { name: 'Mostrar senha' });
    await user.click(toggleButton);
    expect(screen.getByLabelText('Senha')).toHaveAttribute('type', 'text');
    expect(toggleButton).toHaveTextContent('Ocultar');

    await user.click(toggleButton);
    expect(screen.getByLabelText('Senha')).toHaveAttribute('type', 'password');
    expect(toggleButton).toHaveTextContent('Mostrar');
  });

  it('calcula força da senha fraca', async () => {
    const user = userEvent.setup();
    const handleChange = jest.fn();
    render(<PasswordField value="" onChange={handleChange} />);

    await user.type(screen.getByLabelText('Senha'), 'abc');
    expect(handleChange).toHaveBeenCalledTimes(3);
    expect(handleChange).toHaveBeenNthCalledWith(1, 'a');
    expect(handleChange).toHaveBeenNthCalledWith(2, 'b');
    expect(handleChange).toHaveBeenNthCalledWith(3, 'c');
    expect(screen.getByText('Força: fraca')).toBeInTheDocument();
  });

  it('calcula força da senha média', async () => {
    const user = userEvent.setup();
    const handleChange = jest.fn();
    render(<PasswordField value="" onChange={handleChange} />);

    await user.type(screen.getByLabelText('Senha'), 'abc12345');
    expect(handleChange).toHaveBeenCalledTimes(8);
    expect(handleChange).toHaveBeenNthCalledWith(1, 'a');
    expect(handleChange).toHaveBeenNthCalledWith(2, 'b');
    expect(handleChange).toHaveBeenNthCalledWith(3, 'c');
    expect(handleChange).toHaveBeenNthCalledWith(4, '1');
    expect(handleChange).toHaveBeenNthCalledWith(5, '2');
    expect(handleChange).toHaveBeenNthCalledWith(6, '3');
    expect(handleChange).toHaveBeenNthCalledWith(7, '4');
    expect(handleChange).toHaveBeenNthCalledWith(8, '5');
    expect(screen.getByText('Força: média')).toBeInTheDocument();
  });

  it('calcula força da senha forte', async () => {
    const user = userEvent.setup();
    const handleChange = jest.fn();
    render(<PasswordField value="" onChange={handleChange} />);

    await user.type(screen.getByLabelText('Senha'), 'abc12345!@#');
    expect(handleChange).toHaveBeenCalledTimes(11);
    expect(handleChange).toHaveBeenNthCalledWith(1, 'a');
    expect(handleChange).toHaveBeenNthCalledWith(2, 'b');
    expect(handleChange).toHaveBeenNthCalledWith(3, 'c');
    expect(handleChange).toHaveBeenNthCalledWith(4, '1');
    expect(handleChange).toHaveBeenNthCalledWith(5, '2');
    expect(handleChange).toHaveBeenNthCalledWith(6, '3');
    expect(handleChange).toHaveBeenNthCalledWith(7, '4');
    expect(handleChange).toHaveBeenNthCalledWith(8, '5');
    expect(handleChange).toHaveBeenNthCalledWith(9, '!');
    expect(handleChange).toHaveBeenNthCalledWith(10, '@');
    expect(handleChange).toHaveBeenNthCalledWith(11, '#');
    expect(screen.getByText('Força: forte')).toBeInTheDocument();
  });

  it('senha vazia não exibe força', () => {
    render(<PasswordField value="" onChange={() => {}} />);

    expect(screen.queryByText(/Força:/)).not.toBeInTheDocument();
  });
});
